import sys, numpy as np
def key(lo,hi): return tuple(np.round(lo,9))+tuple(np.round(hi,9))
def load(fn):
    S={}
    for l in open(fn):
        a,b,d=l.strip().split(';')
        lo=np.array([float(x) for x in a.split(',')]); hi=np.array([float(x) for x in b.split(',')])
        S[key(lo,hi)]=(lo,hi,int(d))
    return S
def children(lo,hi,d):
    m=(lo[d-1]+hi[d-1])/2
    h1=hi.copy(); h1[d-1]=m; l2=lo.copy(); l2[d-1]=m
    return (lo,h1),(l2,hi)
def build(S,lo,hi):
    """returns nested: ('leaf',lo,hi) or ('split',d,cuts,[children])  with merging"""
    k=key(lo,hi)
    if k not in S: return ('leaf',lo,hi)
    d=S[k][2]
    # collect group: expand same-dim descendants
    pieces=[(lo,hi)]; changed=True
    while changed:
        changed=False; new=[]
        for (l,h) in pieces:
            kk=key(l,h)
            if kk in S and S[kk][2]==d:
                new+=list(children(l,h,d)); changed=True
            else: new.append((l,h))
        pieces=new
    pieces.sort(key=lambda p:p[0][d-1])
    cuts=[p[0][d-1] for p in pieces[1:]]
    return ('split',d,cuts,[build(S,l,h) for l,h in pieces],lo,hi)
def count(t):
    if t[0]=='leaf': return 1
    return 1+sum(count(c) for c in t[3])-0  # node itself + children subtrees
if __name__=='__main__':
    S=load(sys.argv[1])
    lo=np.array([-0.129289,-0.5,-0.5,-0.5,-0.5]); hi=np.array([0.679858,-0.111408,-0.499204,-0.409091,0.5])
    k0=list(S.keys())[0]; lo,hi=S[k0][0],S[k0][1]
    t=build(S,lo,hi)
    print('binary nodes',2*len(S)+1,'merged nodes',count(t))

